import {energy03Data as data} from './energy03-data.js?v=20261027-energy03';
import {energy03Maps} from './energy03-maps.js?v=20261027-energy03';
export {energy03Data} from './energy03-data.js?v=20261027-energy03';
export {energy03Maps} from './energy03-maps.js?v=20261027-energy03';
export const energy03Views={
 'dev-energy3-stakeholders':[['roles','Interests and constraints'],['survey','Read the survey'],['local','National and local'],['discussion','Listen and test claims']],
 'dev-energy3-sustainable-use':[['finite','A finite stock'],['renewal','Renewal has limits'],['efficiency','Same service, less energy'],['scales','Connect the scales']],
 'dev-energy3-management-views':[['household','Household choices'],['organisation','An organisation invests'],['government','Policy into practice'],['judge','Compare the tradeoffs']],
 'dev-energy3-developed-case':[['map','Locate Germany'],['shares','Read sector evidence'],['retrofit','Improve useful services'],['grid','Integrate the system']],
 'dev-energy3-emerging-case':[['map','Locate India'],['capacity','Read capacity evidence'],['rooftop','Solar into a service'],['deliver','Connect and maintain']]
};
export const energy03Requirements=Object.fromEntries(Object.entries(energy03Views).map(([k,v])=>[k,v.map(x=>x[0])]));
export const energy03Animated=(k,v)=>k==='dev-energy3-stakeholders'?v==='discussion':k==='dev-energy3-sustainable-use'?['finite','renewal'].includes(v):k==='dev-energy3-management-views'?v!=='judge':k==='dev-energy3-developed-case'?['retrofit','grid'].includes(v):k==='dev-energy3-emerging-case'?['rooftop','deliver'].includes(v):false;
export const stockEnd=(start,renew,remove)=>start+renew-remove;
export const percentSaving=(before,after)=>(before-after)/before*100;
export const capacityShare=(part,total)=>part/total*100;
export const regionXY=(region,lon,lat)=>{const[a,b,c,d]=energy03Maps[region].extent;return[20+(lon-a)/(b-a)*240,60+(d-lat)/(d-c)*240];};
const T=(x,y,s,z=12)=>`<text x="${x}" y="${y}" font-size="${z}">${s}</text>`;
const line=(d,c='#c2d3cd',w=2)=>`<path d="${d}" fill="none" stroke="${c}" stroke-width="${w}" stroke-linecap="round"/>`;
const dot=(x,y,c='#edb396',r=5)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${c}" stroke="#f1e4ce"/>`;
const box=(x,y,w,a,b)=>`<rect x="${x}" y="${y}" width="${w}" height="${b?64:40}" rx="10" fill="#35566b" stroke="#a6c1c8"/>`+T(x+12,y+24,a)+(b?T(x+12,y+47,b,11):'');
const title=s=>T(20,30,s,13);
const fig=(b,c)=>`<svg viewBox="0 0 440 350" style="background:#203e53;border-radius:12px" role="img" aria-label="${c.replaceAll('&','&amp;').replaceAll('"','&quot;')}"><g fill="#f0f1e9" font-family="sans-serif">${b}</g></svg><p class="geo-caption">${c}</p>`;
const link=(u,t)=>`<a href="${u}" target="_blank" rel="noopener">${t}</a>`;
const table=(cap,heads,rows)=>`<details class="geo-chart-values"><summary>Read the source values</summary><table class="geo-data"><caption>${cap}</caption><thead><tr>${heads.map(s=>`<th scope="col">${s}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr><th scope="row">${r[0]}</th>${r.slice(1).map(s=>`<td>${s}</td>`).join('')}</tr>`).join('')}</tbody></table></details>`;
const sources={attitudes:link(data.attitudes.source,'DESNZ Spring 2026 survey, published 2 July 2026')+'. UK respondent expectations; short-term base 3,374, long-term 3,354. Different response categories and horizons; not complementary percentages or actual future bills. Crown copyright / OGL3.0.',germany:link(data.germany.source,'UBA / AGEE-Stat: 2025 renewable consumption shares')+' · '+link('https://www.iea.org/reports/germany-2025/executive-summary','IEA Germany 2025 policy review')+'. UBA updated 19 October 2026: different named denominators, not additive parts of one mix. The IEA review is dated 7 April 2025; it describes an approach and constraints, not guaranteed outcomes.',india:link(data.india.source,'MNRE / PIB: 30 June 2025 installed-capacity snapshot')+'. GW of capacity, not annual generation or all-energy consumption. Non-fossil includes nuclear; stated rounded cells and reported share retained. Government delivery evidence, not a complete independent impact evaluation.',rooftop:link(data.rooftop.source,'MNRE / PIB: rooftop programme, 25 March 2026')+'. Added capacity as of 20 March 2026, since programme launch in February 2024. Not a household count or annual output; projected jobs and avoided emissions are not treated as measured outcomes.',management:link('https://www.iea.org/reports/germany-2025/executive-summary','IEA: integrated supply, demand, infrastructure and distribution')+' · '+link(data.attitudes.source,'DESNZ: household constraints and expectations')+'. Scenarios, roles, stocks, input savings and token timing are illustrative, not measured policies, budgets or universal group opinions.'};
const source=k=>`<p class="geo-caption">${sources[k]}</p>`;
export function energy03Evidence(k='germany'){
 let b='',c='';
 if(k==='germany'){b=title('GERMANY · RENEWABLE SHARES · 2025')+T(20,52,'Percent of EACH named denominator · zero baseline',11);const labels=['Gross final energy (RED)','Gross electricity','Heating / cooling','Transport'];for(const[i,[n,v]]of data.germany.rows.entries()){const y=98+i*52;b+=T(20,y,labels[i],11)+`<rect x="207" y="${y-14}" width="${v*2.7}" height="23" rx="3" fill="${['#adc5b0','#edb396','#a9c3cc','#d4c6a5'][i]}"/>`+T(217+v*2.7,y+3,v.toFixed(1)+'%',12);}b+=line('M207 295H369')+T(203,315,'0',10)+T(277,315,'30',10)+T(359,315,'60%',10);c='Dated renewable shares in different consumption accounts. Each row has its own denominator; the figures must not be added as if they formed a single fuel mix.';return fig(b,c)+source('germany')+table('UBA 2025 sector shares, webpage vintage 19 October 2026',['Consumption account','Renewable %'],data.germany.rows);}
 if(k==='india'){b=title('INDIA · INSTALLED ELECTRICITY CAPACITY')+T(20,53,'30 June 2025 · GW, not annual generation',11);for(const[i,[n,v]]of [['Thermal',242.04],['Non-fossil subtotal',242.78]].entries()){const y=105+i*70;b+=T(20,y,n,12)+`<rect x="175" y="${y-17}" width="${v/500*210}" height="28" rx="3" fill="${i?'#adc5b0':'#edb396'}"/>`+T(185+v/500*210,y+4,v.toFixed(2),12);}b+=line('M175 207H385')+T(172,224,'0',10)+T(257,224,'250',10)+T(367,224,'500 GW',10)+T(20,259,'Non-fossil: renewables incl. hydro 234.00 GW',12)+T(20,282,'+ nuclear 8.78 GW',12)+T(20,312,'Total:484.82 GW · Reported non-fossil share:50.08%',11);c='Installed capacity snapshot with the non-fossil subtotal decomposed into renewables including large hydro and nuclear. A power capacity is not delivered annual energy.';return fig(b,c)+source('india')+table('30 June 2025 installed electricity capacity; subtotal is not an extra category',['Category','GW'],[...data.india.rows,['Non-fossil subtotal',242.78],['Total',484.82]]);}
 if(k==='rooftop'){b=title('PM SURYA GHAR · REPORTED ADDED CAPACITY')+T(20,58,'As of 20 March 2026 · programme launched February 2024',11)+`<rect x="20" y="105" width="382.6756" height="60" rx="6" fill="#adc5b0"/>`+T(38,143,'9,566.89 MW',26)+line('M20 185H420')+T(20,206,'0',11)+T(340,206,'10,000 MW',11)+box(20,245,400,'Read what is measured','Added power capacity, not homes or annual energy');c='Reported cumulative rooftop capacity added under the programme, with a zero baseline. The figure is a dated government output measure, not measured bill savings, households or jobs.';return fig(b,c)+source('rooftop')+table('Government reported rooftop capacity added under PM Surya Ghar',['As of','Capacity MW'],[['20 March 2026',9566.89]]);}
 b=title('UK BILL EXPECTATIONS · SPRING 2026')+T(20,54,'Different horizons and response categories',11);for(const[i,[n,v]]of data.attitudes.rows.entries()){const y=100+i*105;b+=T(20,y,n.replace(':',': '),13)+`<rect x="20" y="${y+15}" width="${v*4}" height="32" rx="4" fill="${i?'#adc5b0':'#edb396'}"/>`+T(30+v*4,y+38,v+'%',14);}b+=line('M20 288H420')+T(20,309,'0%',10)+T(210,309,'50%',10)+T(391,309,'100%',10);c='Two selected response percentages with different time horizons and bases. These are expectations about bills, not a prediction, support measure or two parts that should sum to 100%.';return fig(b,c)+source('attitudes')+table('Spring 2026 weighted UK survey expectations',['Selected response and horizon','Percent'],data.attitudes.rows);
}
function locator(region){const germany=region==='germany',g=energy03Maps[region],id='e3-map-'+region,[x,y]=regionXY(region,germany?13.4:77.2,germany?52.5:28.6);let b=title(germany?'GERMANY · EUROPEAN CONTEXT':'INDIA · SOUTH ASIAN CONTEXT')+T(20,51,'North ↑ · generalised country geometry',11)+`<defs><clipPath id="${id}"><rect x="20" y="60" width="240" height="240"/></clipPath></defs><rect x="20" y="60" width="240" height="240" fill="#294f65"/><g clip-path="url(#${id})">${g.paths.map(p=>`<path d="${p.d}" fill="${p.code===(germany?'DEU':'IND')?'#b9c9a9':'#6b918b'}" stroke="#d6e0d5" stroke-width="0.8"/>`).join('')}</g>`+dot(x,y)+line(`M${x+5} ${y}H278`)+T(285,y+4,germany?'Berlin':'New Delhi',12)+T(285,250,germany?'Germany':'India',16)+T(285,275,germany?'Developed case':'Emerging case',11)+T(20,329,'Context map, not project sites or resource boundaries.',10);return fig(b,'Actual Natural Earth outlines reprojected to a regional context with an approximate capital marker. Generalised educational geometry, not project footprints or authoritative boundary detail.')+`<p class="geo-caption">${link('https://www.naturalearthdata.com/about/terms-of-use/','Natural Earth public-domain geometry')}.</p>`+source(germany?'germany':'india');}
const house=(t,roof=false)=>`<path d="M55 180L150 100 245 180V290H55Z" fill="#758e87" stroke="#c7d5c9" stroke-width="2"/><path d="M70 180L150 115 230 180" fill="none" stroke="${roof?'#80a8ba':'#dfc49d'}" stroke-width="${roof?17:3+8*t}"/><rect x="85" y="203" width="55" height="50" rx="3" fill="#c4d5cc"/><rect x="169" y="218" width="42" height="72" rx="3" fill="#35566b"/>`;
export function energy03Scene(k,v,t=0){if(!energy03Views[k])return '';if(!energy03Requirements[k].includes(v))v=energy03Requirements[k][0];t=energy03Animated(k,v)?Math.max(0,Math.min(1,Number(t)||0)):0;let b='',c='',s='management';
 if(k==='dev-energy3-stakeholders'){
 if(v==='survey')return energy03Evidence('attitudes');
 if(v==='roles'){b=title('INTERESTS ARE NOT FIXED GROUP OPINIONS')+box(20,65,190,'Individuals','Warmth / bills / values')+box(230,65,190,'Organisations','Jobs / revenue / environment')+box(20,190,190,'Governments','Security / fairness / emissions')+box(230,190,190,'Within-group variation','Different roles and constraints')+T(20,328,'Ask who gains, who pays and what evidence supports a view.',10);c='A framework of plausible interests, not a survey assigning identical opinions to every resident, company or government.';}
 else if(v==='local'){b=title('ONE PROPOSAL · DIFFERENT SCALES')+box(20,65,400,'National goals','Reliable services / emissions / investment')+box(20,160,190,'Local potential benefits','Jobs / shared revenue')+box(230,160,190,'Local possible costs','Landscape / wildlife / disruption')+line('M220 135V150M220 150H115V158M220 150H325V158')+T(20,309,'Illustrative proposal; no measured site or fixed preference.',10);c='A hypothetical project comparison. National support can coexist with concerns about one site; local benefits and costs require evidence.';}
 else{b=title('PARTICIPATION → EVIDENCE → REASONS')+box(20,70,180,'Hear different voices','Accessible participation')+box(240,70,180,'Test claims','Evidence and alternatives')+box(120,245,200,'Explain the decision','Record tradeoffs and review')+line('M200 104H233M330 140L250 235')+dot(200+33*t,104)+dot(330-80*t,140+95*t)+T(20,330,'Discussion informs a decision; it does not guarantee agreement.',10);c='An illustrative decision process. Moving tokens show information transfer, not real public support or proof that consultation resolved every disagreement.';}
 }
 if(k==='dev-energy3-sustainable-use'){
 if(v==='finite'||v==='renewal'){const renew=v==='renewal'?10:0,remove=v==='renewal'?25:20,start=v==='renewal'?80:100,end=stockEnd(start,renew,remove),stock=start+(end-start)*t;b=title(v==='finite'?'FINITE STOCK · EXTRACTION WITHOUT REPLACEMENT':'RENEWAL DOES NOT GUARANTEE A STABLE STOCK')+T(20,62,'Invented teaching units, fixed assumed rates',11)+`<rect x="50" y="100" width="300" height="75" rx="7" fill="#2e4e61" stroke="#b9cfc8"/><rect x="50" y="100" width="${stock*3}" height="75" rx="7" fill="#aec6b0"/>`+T(65,145,'Stock: '+stock.toFixed(0),20)+line('M357 137H417')+dot(357+60*t,137)+(renew?line('M5 137H43')+dot(5+38*t,137,'#b1cfd2'):'')+T(20,222,`Start ${start} + renewal ${renew} − use ${remove}`,15)+T(20,264,'End: '+end+' units',18)+T(20,330,'Replay restarts the example, not a real resource.',11);c=renew?'An invented biomass-stock balance where removal exceeds replenishment. Growth, habitats and harvest vary in reality; the loop is not an ecological recovery forecast.':'A finite-resource teaching balance. Lower extraction can slow depletion, but playback does not make geological fuel regrow.';}
 else if(v==='efficiency'){b=title('SAME ADEQUATE SERVICE · LOWER INPUT')+box(20,65,400,'Useful service held constant','Comfort / task conditions assumed equal')+`<rect x="20" y="170" width="400" height="35" fill="#edb396"/><rect x="20" y="240" width="300" height="35" fill="#aec6b0"/>`+T(25,159,'Before:100 units',13)+T(25,229,'After:75 units',13)+T(20,330,'Toy comparison; real costs, behaviour and conditions vary.',10);c='Invented energy inputs for the same adequate service. The saving is not a measured retrofit outcome, universal bill reduction or encouragement to live without warmth.';}
 else{b=title('MANAGEMENT AT CONNECTED SCALES')+box(20,65,400,'Local / household','Efficient services / siting / community access')+box(20,155,400,'National','Grids / standards / investment / worker support')+box(20,245,400,'International','Climate cooperation / finance / trade / supply chains');c='A static scale framework. Actions interact across borders and sectors; no single scale automatically solves every resource or affordability problem.';}
 }
 if(k==='dev-energy3-management-views'){
 if(v==='household'){b=title('A HOUSEHOLD NEEDS FEASIBLE OPTIONS')+house(t)+line('M255 205H410')+dot(255+155*t,205,'#edb396',6-3*t)+T(275,113,'Support / control',12)+T(275,138,'Building condition',11)+T(275,163,'Affordable service',11)+T(20,329,'Illustrative efficiency upgrade, not guaranteed savings.',10);c='Conceptual household insulation and lower heat-loss symbolism. Property control, finance, condition and adequate warmth affect feasible choices; token size is not measured heat flow.';}
 else if(v==='organisation'){b=title('UPFRONT INVESTMENT → OPERATING CHANGE')+`<path d="M30 155L100 110V155L170 110V155H250V290H30Z" fill="#7c9187" stroke="#cbd7c8"/><rect x="58" y="195" width="155" height="57" rx="8" fill="#35576b"/><g transform="translate(133 223) rotate(${t*180})"><path d="M-25 0H25M0-25V25" stroke="#d8c8a7" stroke-width="10"/></g>`+box(270,80,150,'Finance / skills','Time and disruption')+line('M255 225H415')+dot(255+160*t,225,'#b5cfb8')+T(20,328,'A possible company choice; not every organisation agrees.',10);c='Illustrative investment-to-service mechanism, not a real factory’s measured costs or savings. Organisations can value efficiency while facing capital and implementation barriers.';}
 else if(v==='government'){b=title('POLICY NEEDS IMPLEMENTATION AND MONITORING')+box(20,65,190,'Standards / investment','Public tools and choices')+box(230,65,190,'Targeted support','Access / costs / transition')+box(120,245,200,'Measure actual outcomes','Delivery / fairness / review')+line('M115 140L180 235M325 140L250 235')+dot(115+65*t,140+95*t)+dot(325-75*t,140+95*t)+T(20,328,'Funding and rules are means, not proof of every outcome.',10);c='A conceptual policy-to-outcome pathway. Moving tokens do not represent actual budget flows, approval or guaranteed public benefits.';}
 else{b=title('COMPARE OPTIONS WITH EXPLICIT CRITERIA')+box(20,65,400,'Service and security','Useful output / reliability / supply resilience')+box(20,155,400,'Costs and distribution','Upfront and later costs / who can participate')+box(20,245,400,'Environment and accountability','Lifecycle effects / evidence / review');c='A decision matrix without a universal winner. Weighting and evidence need explanation; selected answers do not establish a student’s full constructed judgement.';}
 }
 if(k==='dev-energy3-developed-case'){
 if(v==='map')return locator('germany');if(v==='shares')return energy03Evidence('germany');s='germany';
 if(v==='retrofit'){b=title('GERMANY · EFFICIENT SERVICES AND CLEANER HEAT')+house(t)+line('M255 205H410')+dot(255+155*t,205,'#edb396',7-4*t)+T(267,105,'Upgrade buildings',12)+T(267,130,'Suitable heating',12)+T(267,155,'Adequate comfort',12)+T(20,329,'Illustrative mechanism, not German household measurements.',10);c='An illustrative efficiency component of the approach described in the 2025 review. Costs, buildings and occupants differ; the diagram does not measure national savings or promise a particular bill outcome.';}
 else{b=title('GERMANY · INTEGRATE SUPPLY AND SERVICES')+box(20,65,190,'Variable renewable supply','Connections / suitable sites')+box(230,65,190,'Grids and flexibility','Storage / shifting demand')+box(120,245,200,'Useful energy services','Reliability / cost / access')+line('M200 100H223M325 140L250 235')+dot(200+23*t,100)+dot(325-75*t,140+95*t)+T(20,329,'Storage shifts earlier energy; it does not create it.',10);c='A conceptual system-integration pathway, not a dispatch forecast or universal success claim. Generation, networks and demand must work together.';}
 }
 if(k==='dev-energy3-emerging-case'){
 if(v==='map')return locator('india');if(v==='capacity')return energy03Evidence('india');s=v==='rooftop'?'rooftop':'india';
 if(v==='rooftop'){b=title('INDIA · ROOFTOP SOLAR TO A USEFUL SERVICE')+house(0,true)+`<circle cx="45" cy="73" r="21" fill="#dfc596"/>`+line('M65 90L120 133','#e0cb9e',3)+dot(65+55*t,90+43*t,'#e0cb9e',3)+box(270,100,150,'Connection / meter','Operate and maintain')+line('M220 175H260V140M345 170V275H220')+dot(220+40*t,175,'#b2cfba')+dot(345-125*t,275,'#b2cfba')+T(20,330,'Financial support and installation are steps, not equal savings.',10);c='Illustrative rooftop generation, connection and use linked to PM Surya Ghar. Not measured output, a promise of universal eligibility or identical savings; actual conditions and operation matter.';}
 else{b=title('INDIA · FROM CAPACITY TO RELIABLE ACCESS')+box(20,65,190,'Install equipment','Finance / land or roof / skills')+box(230,65,190,'Connect and operate','Grid / safe upkeep / flexibility')+box(120,245,200,'Evaluate real services','Output / reliability / affordability')+line('M200 100H223M325 140L250 235')+dot(200+23*t,100)+dot(325-75*t,140+95*t)+T(20,329,'A capacity headline is not a full sustainability assessment.',10);c='A conceptual delivery-to-service pathway, not a measured national rollout or proof of universal access. Evaluate actual output, who benefits and environmental effects.';}
 }
 return fig(b,c)+source(s);
}
